package com.securevault.controller;
import com.securevault.entity.User;import com.securevault.repository.UserRepository;import com.securevault.service.MfaService;import org.springframework.http.*;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/mfa") @CrossOrigin(origins="http://localhost:5173") public class MfaController{private final UserRepository users;private final MfaService mfa;public MfaController(UserRepository u,MfaService m){users=u;mfa=m;}private User u(Authentication a){return users.findByEmail(a.getName()).orElseThrow();}@GetMapping("/status")public Map<String,Object> status(Authentication a){return Map.of("enabled",u(a).isMfaEnabled());}@PostMapping("/setup")public Map<String,Object> setup(Authentication a){User u=u(a);String s=mfa.newSecret();u.setMfaSecret(s);users.save(u);return Map.of("secret",s,"code",mfa.currentCode(s));}@PostMapping("/enable")public ResponseEntity<?> enable(@RequestBody Map<String,String>b,Authentication a){User u=u(a);if(u.getMfaSecret()==null||!mfa.verify(u.getMfaSecret(),b.get("code")))return ResponseEntity.badRequest().body(Map.of("message","Invalid MFA code"));u.setMfaEnabled(true);users.save(u);return ResponseEntity.ok(Map.of("message","MFA enabled"));}@PostMapping("/disable")public Map<String,Object> disable(Authentication a){User u=u(a);u.setMfaEnabled(false);users.save(u);return Map.of("enabled",false);}}
